class Solution {
public:
    int minimizeConcatenatedLength(vector<string>& words) {
        int n = words.size();
        int memo[1005][26][26];
        memset(memo, -1, sizeof(memo));
        auto dp = [&](auto& self, int idx, int first, int last) -> int {
            if (idx == n) return 0;
            if (memo[idx][first][last] != -1) return memo[idx][first][last];
            const string& w = words[idx];
            int w_first = w.front() - 'a', w_last = w.back() - 'a', w_len = w.size();
            int save1 = (last == w_first) ? 1 : 0;
            int res1 = (w_len - save1) + self(self, idx + 1, first, w_last);
            int save2 = (w_last == first) ? 1 : 0;
            int res2 = (w_len - save2) + self(self, idx + 1, w_first, last);
            return memo[idx][first][last] = min(res1, res2);
        };
        return (int)words[0].size() + dp(dp, 1, words[0].front() - 'a', words[0].back() - 'a');
    }
};

import java.util.Arrays;

class Solution {
    public int minimizeConcatenatedLength(String[] words) {
        int n = words.length;
        int[][][] memo = new int[n][26][26];
        for (int[][] mat : memo) {
            for (int[] row : mat) Arrays.fill(row, -1);
        }
        return words[0].length() + dfs(words, 1, words[0].charAt(0) - 'a', words[0].charAt(words[0].length() - 1) - 'a', memo);
    }

    private int dfs(String[] words, int idx, int first, int last, int[][][] memo) {
        if (idx == words.length) return 0;
        if (memo[idx][first][last] != -1) return memo[idx][first][last];
        String w = words[idx];
        int wFirst = w.charAt(0) - 'a', wLast = w.charAt(w.length() - 1) - 'a', wLen = w.length();
        int save1 = (last == wFirst) ? 1 : 0;
        int res1 = (wLen - save1) + dfs(words, idx + 1, first, wLast, memo);
        int save2 = (wLast == first) ? 1 : 0;
        int res2 = (wLen - save2) + dfs(words, idx + 1, wFirst, last, memo);
        return memo[idx][first][last] = Math.min(res1, res2);
    }
}

var minimizeConcatenatedLength = function(words) {
    const n = words.length;
    const memo = new Map();
    function dp(idx, first, last) {
        if (idx === n) return 0;
        const key = `${idx},${first},${last}`;
        if (memo.has(key)) return memo.get(key);
        const w = words[idx];
        const wFirst = w.charCodeAt(0) - 97;
        const wLast = w.charCodeAt(w.length - 1) - 97;
        const wLen = w.length;
        const save1 = (last === wFirst) ? 1 : 0;
        const res1 = (wLen - save1) + dp(idx + 1, first, wLast);
        const save2 = (wLast === first) ? 1 : 0;
        const res2 = (wLen - save2) + dp(idx + 1, wFirst, last);
        const ans = Math.min(res1, res2);
        memo.set(key, ans);
        return ans;
    }
    const first0 = words[0].charCodeAt(0) - 97;
    const last0 = words[0].charCodeAt(words[0].length - 1) - 97;
    return words[0].length + dp(1, first0, last0);
};
